        return a
    else:
        return 2

def specified_element(lst, index):
    result = []
    for sub_list in lst:
        if index < len(sub_list):
            result.append(sub_list[index])
    return result

def min_length_list(lst):
    min_length = min(len(x) for x in lst)
    return min_length, [x for x in lst if len(x) == min_length]

def check_equilateral(a, b, c):
    if a == b == c:
        return True
    else:
        return False
